root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign17-beta-byte-probe-retry-check';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='8a7bf9b3dcc072116b02ee74622468c5aff929342c628dc1cd8b9a9809abae1b' and sha(m)=='0d07d24d62e7a191e75a08283b1b91c20d2fb33072a962f70786ca43170b8396';rows=json.loads(m.read_text())['rows'];names=['Sign17UnivariateDegreeProbe','Sign17AxisDegreeBase','Sign17AxisDegreeRoot','Sign17AxisDegreeScale','Sign17AxisBindingBase','Sign17AxisBindingFactors','Sign17AxisBindingRoot','Sign17AxisNaDegree','Sign17AxisOtherDegree','Sign17AxisNoncancel','Sign17AxisSeedDegree','Sign17AxisDiagonalDegree','Sign17AxisDiagonalBinding','Sign17AxisDegreeLower','Sign17ExactDegree','Sign17BetaBytePattern'];assert [r['module'].split('.')[-1] for r in rows]==names;seen={'Sign17DegreeCompose','Equiv'}
