 if i==14:assert row['imports']==['DiophantineConsistency.Sign17AxisDegreeLower'] and 'theorem current_port_positive' in s and 'unfold CurrentMasks2011.radix' in s and 'theorem current_port_nonzero' in s and 'theorem abstract_exact (p : Fin 4 → ℤ) (hz : p 0 ≠ 0)' in s and 'theorem current_exact : Sign17CurrentExpression.expression.toPolynomial.totalDegree = 96' in s
 if i==15:assert row['imports']==['DiophantineConsistency.Sign17ExactDegree'] and 'theorem ff_digits_add_one (n : ℕ)' in s and 'theorem beta_pattern' in s and 'theorem current_port0_pattern' in s and s.count('31 :: List.replicate 11814 255')==4
